#!/bin/bash
set -euo pipefail
RUN=/var/lib/kalshi-study/reproduction-btc-20261117
exec >>"$RUN/provisional-gradient.log" 2>&1
trap 'rc=$?; echo "FAIL $rc $(date -u --iso-8601=seconds)" | tee "$RUN/provisional-gradient-status.txt"' ERR
printf '%s' '' | base64 -d > "$RUN/gradient_recreated_model.py"
echo "WAITING_FOR_PROVISIONAL $(date -u --iso-8601=seconds)" | tee "$RUN/provisional-gradient-status.txt"
while ! grep -q '^COMPLETE' "$RUN/provisional-status.txt" 2>/dev/null; do
 if grep -q '^FAIL' "$RUN/provisional-status.txt" 2>/dev/null; then echo 'Provisional run failed'; exit 1; fi
 sleep 30
done
echo "RUNNING gradients $(date -u --iso-8601=seconds)" | tee "$RUN/provisional-gradient-status.txt"
export PYTHONPATH=/opt/kalshi PYTHONWARNINGS=ignore OPENBLAS_NUM_THREADS=1
/opt/kalshi/venv/bin/python -u "$RUN/gradient_recreated_model.py"
/opt/kalshi/venv/bin/python - <<'PYCODE'
from azure.identity import DefaultAzureCredential
from azure.storage.blob import BlobServiceClient
root='/var/lib/kalshi-study/reproduction-btc-20261117/provisional-output/'
c=BlobServiceClient('https://kalshiobfdfaed53.blob.core.windows.net',credential=DefaultAzureCredential()).get_container_client('tape')
for n in ('BTC_gradient.json','BTC_gradient.csv'):
 with open(root+n,'rb') as f:c.upload_blob('research/reproductions/btc-tradecheck-20261117/'+n,f,overwrite=False)
print('Uploaded provisional gradient files')
PYCODE
echo "COMPLETE $(date -u --iso-8601=seconds)" | tee "$RUN/provisional-gradient-status.txt"
